  ["Start VR hand tracking"] = "VR-Handtracking starten",
  ["Log VR Diag"] = "VR-Diagnose protokollieren",
  ["Dumps gizmo vs. bone poses to vrik_diag.txt (next to dxgi.dll)\nfor tuning the arm IK. Same as the CET 'Log VR Diag' button."] = "Schreibt Gizmo- und Knochenposen nach vrik_diag.txt (neben dxgi.dll)\nzum Abstimmen des Arm-IK. Wie die CET-Schaltfläche „Log VR Diag“.",
  ["Roomscale movement"] = "Roomscale-Bewegung",
  ["Move the player capsule with physical horizontal head movement.\nUses native collision/steps and preserves stick or WASD movement.\nSuspended in menus, vehicles and scripted movement."] = "Bewegt die Spielerkapsel mit der physischen horizontalen Kopfbewegung.\nNutzt die native Kollision/Stufen und behält Stick- oder WASD-Bewegung bei.\nIn Menüs, Fahrzeugen und geskripteter Bewegung ausgesetzt.",
  ["Stick / snap only"] = "Nur Stick / Snap",
  ["Head + free-look cone"] = "Kopf + Freisicht-Kegel",
  ["HMD + controllers"] = "HMD + Controller",
  ["Hybrid (default)"] = "Hybrid (Standard)",
  ["Body rotation"] = "Körperdrehung",
  ["Hybrid: use the head cone while upright.\nLooking down by 10 degrees or bending by 5 degrees uses HMD + controllers.\nReturn below 8 / 3 degrees; the current body heading is preserved at handover.\nHMD + controllers always disables the body cones. Missing tracking holds heading."] = "Hybrid: Kopfkegel in aufrechter Haltung.\nBlick 10° nach unten oder 5° Vorbeugen nutzt HMD + Controller.\nZurück unter 8 / 3°; die aktuelle Körperrichtung bleibt beim Wechsel erhalten.\nHMD + Controller deaktiviert die Körperkegel immer. Ohne Tracking bleibt die Richtung.",
  ["Never (VRIK always on)"] = "Nie (VRIK immer an)",
  ["Staged scenes and up (Tier 2+)"] = "Inszenierte Szenen und höher (Tier 2+)",
  ["Tier 3 and up"] = "Tier 3 und höher",
  ["Cinematics (Tier 4+)  [default]"] = "Zwischensequenzen (Tier 4+)  [Standard]",
  ["Full cinematics only (Tier 5)"] = "Nur volle Zwischensequenzen (Tier 5)",
  ["Suspend VRIK in cutscenes (on foot)"] = "VRIK in Zwischensequenzen pausieren (zu Fuß)",
  ["Applies only on foot. VRIK yields to the scene animation at or above this tier.\nThe vehicle threshold is configured separately below."] = "Gilt nur zu Fuß. VRIK überlässt ab dieser Stufe der Szenenanimation die Kontrolle.\nDie Fahrzeugschwelle wird unten separat eingestellt.",
  ["Suspend VRIK in cutscenes (vehicle)"] = "VRIK in Zwischensequenzen pausieren (Fahrzeug)",
  ["Applies in vehicles, including passenger window combat.\nVRIK yields to the scene animation at or above this tier. Never keeps VRIK enabled."] = "Gilt in Fahrzeugen, auch beim Kampf aus dem Beifahrerfenster.\nVRIK überlässt ab dieser Stufe der Szenenanimation die Kontrolle. „Nie“ lässt VRIK aktiv.",
  ["Free-look cone"] = "Freisicht-Kegel",
  ["%.0f deg"] = "%.0f°",
  ["How far your head may turn before the body starts coming around.\nThe body settles toward the centre, then restores the full free-look zone.\nDefault: 10 degrees. Hybrid uses this value while looking ahead."] = "Wie weit sich dein Kopf drehen kann, bevor der Körper nachdreht.\nDer Körper pendelt sich zur Mitte ein und stellt dann die volle Freisicht-Zone wieder her.\nStandard: 10°. Hybrid nutzt diesen Wert beim Blick nach vorn.",
  ["Free-look cone when looking down"] = "Freisicht-Kegel beim Blick nach unten",
  ["Extra room to reach chest-mounted items.\nBlends in from 10 to 30 degrees of downward head tilt.\nNever narrows the normal cone; set the same value to disable widening."] = "Zusätzlicher Spielraum, um an Gegenstände an der Brust zu greifen.\nBlendet bei 10 bis 30° Kopfneigung nach unten ein.\nVerengt nie den normalen Kegel; derselbe Wert schaltet die Erweiterung aus.",
  ["Free-look cone in water"] = "Freisicht-Kegel im Wasser",
  ["One fixed cone on the surface and underwater.\nLooking down and physical bending do not widen it. Default: 5 degrees."] = "Ein fester Kegel an der Oberfläche und unter Wasser.\nBlick nach unten und Vorbeugen erweitern ihn nicht. Standard: 5°.",
  ["Body free-look cones are disabled in HMD + controllers mode."] = "Körper-Freisicht-Kegel sind im Modus HMD + Controller deaktiviert.",
  ["Hybrid: head cone upright; HMD + controllers when looking down or bending."] = "Hybrid: Kopfkegel aufrecht; HMD + Controller beim Blick nach unten oder Vorbeugen.",
  ["Body movement free zone"] = "Freie Zone für Körperbewegung",
