  ["AUTO-CALIBRATING: stretch arms STRAIGHT OUT to the sides,"] = "AUTOKALIBRIERUNG: Arme GERADE ZUR SEITE ausstrecken,",
  ["stand straight facing forward. Hold for %.1fs (%.0f%%)."] = "aufrecht nach vorn stehen. %.1f s halten (%.0f%%).",
  ["Start Auto-Calibration (T-pose, 4s)"] = "Autokalibrierung starten (T-Pose, 4 s)",
  ["Press once, then stretch BOTH gizmo hands OUT to the sides at shoulder height\nand stand straight facing forward. The mod measures the visible controller\npositions, computes shoulder pivots + arm scale, and saves the result\nto vrik_calibration.ini."] = "Einmal drücken, dann BEIDE Gizmo-Hände auf Schulterhöhe ZUR SEITE strecken\nund aufrecht nach vorn stehen. Die Mod misst die sichtbaren Controller-\npositionen, berechnet Schulterpunkte + Armskala und speichert das Ergebnis\nin vrik_calibration.ini.",
  ["Saved."] = "Gespeichert.",
  ["Camera: neck + 15 cm forward, eyes + 10 cm up"] = "Kamera: Hals + 15 cm vor, Augen + 10 cm hoch",
  ["Reset camera to neck"] = "Kamera auf Hals zurücksetzen",
  ["Uses the neutral neck, 15 cm forward and 10 cm above reference eyes.\nResets camera trims; no stance, head direction or Bake measurement is needed."] = "Nutzt den neutralen Hals, 15 cm vor und 10 cm über den Referenzaugen.\nSetzt Kamera-Feinanpassungen zurück; Haltung, Kopfrichtung oder Bake-Messung sind nicht nötig.",
  ["Clear trim"] = "Feinanpassung löschen",
  ["camera mount: R %.3f  Fwd %.3f  Up %.3f"] = "Kamerahalterung: R %.3f  Vor %.3f  Hoch %.3f",
