  ["Stereo module not installed."] = "Stereomodul nicht installiert.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Die Engine-Hooks wurden nicht geladen, daher ist alles darunter wirkungslos und das Headset läuft im einfachen Mono-Pfad. Entweder ist CyberpunkVR_StereoModuleEnable 0 oder bin\\x64\\vrport_nostereo.txt existiert. Siehe die Zeile \"Stereo:\" in cyberpunkvrport.log.",
  ["LEFT"] = "LINKE",
  ["RIGHT"] = "RECHTE",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Stereo aktiv  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Derzeit kein zweites Auge -> beide Augen erhalten MAIN (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "In Menüs und beim Laden normal. Bleibt es im Spiel so: Die VRCAM-Komponente ist aus oder vrcam.json nennt eine Kamera, die die Spielerentität nicht hat.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Stereo-Übergabe aus -> beide Augen erhalten MAIN (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "vrcam-Augenalter %u ms  (veraltet ab %u)   Augenübergaben %llu",
  ["vrcam eye: never produced a frame"] = "vrcam-Auge: noch nie ein Bild erzeugt",
  ["Send VRCAM to the %s EYE"] = "VRCAM an das %s AUGE senden",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Aus = altes Verhalten, MAIN in beide Augen dupliziert.\nAn = das %s Auge erhält die eigene Endfarbe der VRCAM-Ansicht --\ndasselbe Bild wie der Desktop-Spiegel -- neu codiert in das\nsRGB-Format der Swapchain und auf die Augengröße skaliert.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "Snapshot-Kopien %llu   Auslassungen %llu   vrcam-RTV-Treffer %llu",
  ["Eye staleness limit (ms)"] = "Veraltungsgrenze des Auges (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Wie lange das letzte VRCAM-Bild nutzbar bleibt. Danach fällt das %s\nAuge auf MAIN zurück -- ein eingefrorenes Auge, während das andere sich bewegt,\nist viel unangenehmer als Mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (folgt dem Upscaler von MAIN, kein Schalter)",
  ["ON"] = "AN",
  ["off"] = "aus",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "An, sobald MAIN mit DLSS hochskaliert: vrcam erhält einen eigenen\nStreamline-Viewport und rendert unter seiner Zielauflösung.\nAus bei DLAA / TAA / ohne Upscaler. Änderbar in den Grafikeinstellungen\ndes Spiels, nicht hier.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "VRCAM-Projektion an MAIN angleichen  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "VRCAM-Komponente  (RTTI-Schalter: AN/AUS erzwingen)",
  ["component %s   camera %s"] = "Komponente %s   Kamera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "Ansichtsknoten: main %llu   andere %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "VRCAM-Spiegel  (eigenes Fenster, zur Aufnahme)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (Asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnose",
  ["Compact ADS camera telemetry (in-headset)"] = "Kompakte ADS-Kamera-Telemetrie (im Headset)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Ein kleines Panel, das nach dem Schließen von F10 sichtbar bleibt und zeigt, was die ENGINE beim Anheben der Visierung mit der Kamera gemacht hat:\nDelta und Spitze in Zentimetern, rechts/vor/hoch in der eigenen Basis der Blickrichtung, gegenüber einer beim Hüftfeuer erfassten Basis.\nDie Stereo-Übergabe bleibt unberührt.",
  ["Telemetry X"] = "Telemetrie X",
  ["Telemetry Y"] = "Telemetrie Y",
  ["Normalised position in the eye image"] = "Normierte Position im Augenbild",
  ["Stereo logging -> cyberpunkvrport.log"] = "Stereo-Protokoll -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Festgeschriebener Snapshot des VRCAM-Endbilds",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Aus = das temporäre Ziel der Engine direkt lesen. Dieses Ziel ist eine\nFrame-Graph-Zuweisung, die ein späterer Durchlauf wiederverwendet, was\ndas Bild hell/dunkel wechseln ließ. An lassen.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Snapshot am Tonemap-Knoten statt RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "CPU-Profiler der Knoten  (eigene+inkl. ms pro Knoten)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "Bild %.2f ms   Dispatch: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Knoten-Audit -> Protokoll  (setzt Fenster zurück)",
  ["top %d by self ms/frame   (main | vrcam)"] = "Top %d nach eigenen ms/Bild   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Fahren -- Hände am Lenkrad",
  ["Grab the wheel with the grips"] = "Lenkrad mit den Griffen greifen",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Beim FAHREN eine Hand dorthin bringen, wo die Fahranimation das\nLenkrad (oder den Lenker) hält, und den Griff drücken: Der Arm wird\nder Spielanimation übergeben -- Hand am Lenkrad, Finger darum\ngelegt -- statt dem Controller zu folgen. Griff loslassen, und er\nkehrt zu deiner Hand zurück.\n\nJede Hand ist unabhängig: eine am Lenkrad, die andere an der\nWaffe. Solange eine Hand am Lenkrad ist, tut dieser Griff nichts anderes (kein\nZiehen aus dem Holster, kein Magazingriff).",
  ["Grab radius (m)"] = "Greifradius (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Wie nah deine Hand an der animierten Hand sein muss, damit der\nGriff als Lenkradgriff zählt. Größer = ein unsichtbares Lenkrad leichter\nzu fassen; zu groß, und jeder Griff im Auto greift das Lenkrad.",
  ["Car full lock at (deg)"] = "Volleinschlag bei (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Lenkempfindlichkeit: Handdrehung von der Griffposition bis zum Volleinschlag.\nEine Hand nutzt eine an der Griffstelle kalibrierte Nabe; zwei ihre Verbindungslinie.\nHinzufügen oder Lösen einer Hand behält den aktuellen Einschlag bei.\n180 = eine halbe Drehung bis zum Anschlag in jede Richtung (Standard). Weniger = empfindlicher.\nDas Lenkrad im Innenraum hat den doppelten nativen Weg; der Radeinschlag bleibt gleich.\nWeg über den Volleinschlag hinaus behält dieselbe Neutralstellung.",
  ["Steering deadzone (deg)"] = "Lenk-Totzone (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Neigung um die Mitte, die überhaupt nicht lenkt.\nErhöhen, wenn das Auto zieht, während du das Lenkrad gerade hältst;\njedes Grad hier ist ein Grad totes Lenkrad außerhalb der Mitte.\nDer volle Bereich endet trotzdem bei „Volleinschlag bei“, daher\nlässt eine breitere Totzone die Lenkung nicht springen.",
  ["Steering prediction"] = "Lenkvorhersage",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Sagt eine fortgesetzte Kurve sanft aus der jüngsten Handbewegung voraus.\nBegrenzt auf 8 ms und 0.5°; die Mitte bleibt unverändert.\nDie Vorhersage stoppt bei Pause, Richtungswechsel oder Griffwechsel.\nStandardmäßig aus. Den Beginn einer Kurve kann sie nicht vorhersehen.",
  ["Prediction horizon (ms)"] = "Vorhersagehorizont (ms)",
  ["Horn -- hand on the wheel hub"] = "Hupe -- Hand auf der Lenkradnabe",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Beim FAHREN eine Hand auf die MITTE des Lenkrads legen -- dort, wo man\neine echte Hupe drückt --, und das Auto hupt, solange sie dort bleibt.\nKein Griff nötig; eine Hand, die das Lenkrad GREIFT, hupt nie.",
  ["Horn hub radius (m)"] = "Hupen-Nabenradius (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Wie nah an der Lenkradmitte die Hand als auf der Nabe gilt.\nGrößer = Hupe ohne Hinsehen leichter zu finden; zu groß,\nund es reicht bis zum Kranz, sodass jeder Griff hupt.",
  ["Trigger fires the gun while driving"] = "Abzug feuert die Waffe beim Fahren",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Zieh auf dem Fahrersitz eine Waffe, und der RECHTE ABZUG ist nicht mehr\nGas, sondern die Waffe: mit der linken Hand am Lenkrad fahren und\nmit der rechten schießen.\n\nDas Gas RASTET auf dem Wert ein, den es beim Ziehen der Waffe hatte, sodass\ndas Auto weiterrollt, und der LINKE STICK vor/zurück passt die Geschwindigkeit an, während\ndu schießt. Waffe wegstecken, und der Abzug ist wieder Gas.\n\nSolange die Waffe gezogen ist, belegt die Anpassung vor/zurück des linken\nSticks: kein Lehnen / Wippen und keine Autofahr-Geste, bis du wegsteckst.",
  ["Throttle trim rate (/s)"] = "Gasanpassungsrate (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Wie viel des vollen Gaswegs der linke Stick pro Sekunde hinzufügt\noder wegnimmt, solange eine Waffe gezogen ist.\n0.5 = zwei Sekunden halten von Leerlauf bis Vollgas.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "Fahren %d   am Lenkrad  L %d R %d   Halten  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "Lenkung  %+.1f°  ->  Stick %+.2f     Hupe  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "SITZ-KAMERAVERSATZ",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Kopfversätze in ALLGEMEIN sind eine Kalibrierung im Stehen. Im Sitzen ist die\nFahrzeugkamera des Spiels schon dort, wo sie sein soll -- deshalb verwirft der Port\nim Fahrzeug seine zwei automatischen Werte --, und ein Stehversatz trägt die Sicht\nvom Sitz weg, statt sie zu korrigieren.\n\nDiese drei werden zu den Kopfreglern addiert, solange du im Fahrzeug bist, und\nbeim Aussteigen ignoriert, sodass Auto und Straße getrennt eingestellt werden\nkönnen. Null = das Auto behält genau seinen heutigen Versatz.",
