  ["waiting"] = "wartet",
  ["CPU: captured frame cadence. GPU: graphics-queue frame interval. Peaks: last 2 seconds."] = "CPU: Takt der erfassten Bilder. GPU: Bildintervall der Grafik-Queue. Spitzen: letzte 2 Sekunden.",
  ["Output FPS excludes repeated frames; it is not a headset scanout measurement."] = "Ausgabe-FPS ohne wiederholte Bilder; keine Messung der Headset-Abtastung.",
  ["Lows use the mean of the slowest 1%% / 0.1%% of real-frame intervals. Hardware polling: 1 Hz."] = "Tiefs nutzen den Mittelwert der langsamsten 1%% / 0.1%% der echten Bildintervalle. Hardware-Abfrage: 1 Hz.",
  ["FPS overlay and statistics are off."] = "FPS-Overlay und Statistik sind aus.",
  ["Recenter HMD (F7)"] = "HMD zentrieren (F7)",
  ["GENERAL"] = "ALLGEMEIN",
  ["CAS Sharpening"] = "CAS-Schärfung",
  ["Contrast-adaptive sharpening for both eyes. 0 = off, 1 = full strength. Disabled automatically with game DLAA."] = "Kontrastadaptive Schärfung für beide Augen. 0 = aus, 1 = volle Stärke. Bei DLAA im Spiel automatisch deaktiviert.",
  ["FIXED FOVEATED RENDERING"] = "FESTES FOVEATED RENDERING",
  ["Peripheral quality"] = "Randqualität",
  ["Off"] = "Aus",
  ["Quality"] = "Qualität",
  ["Balanced"] = "Ausgewogen",
  ["Performance"] = "Leistung",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "Die Mitte folgt DLSS/DLAA des Spiels. DLAA am Rand nutzt 100%% / 75%% / 50%% der Renderauflösung des Spiels.",
  ["Center width"] = "Mittenbreite",
  ["Full-quality region width as a percentage of each eye image."] = "Breite des Bereichs voller Qualität in Prozent jedes Augenbilds.",
  ["Center height"] = "Mittenhöhe",
  ["Full-quality region height as a percentage of each eye image."] = "Höhe des Bereichs voller Qualität in Prozent jedes Augenbilds.",
  ["Center offset X"] = "Mittenversatz X",
  ["Percentage of eye-image width. Negative = left, positive = right."] = "Prozent der Augenbildbreite. Negativ = links, positiv = rechts.",
  ["Center offset Y"] = "Mittenversatz Y",
  ["Percentage of eye-image height. Negative = up, positive = down toward the hands."] = "Prozent der Augenbildhöhe. Negativ = oben, positiv = unten zu den Händen.",
  ["Show region boundary"] = "Bereichsgrenze anzeigen",
  ["DLSS GPU: native %.2f ms / foveated %.2f ms"] = "DLSS GPU: nativ %.2f ms / foveated %.2f ms",
  ["Shared sun shadows"] = "Gemeinsame Sonnenschatten",
  ["Render sun cascades once for both eyes. Shadow quality and distance remain controlled by the game."] = "Rendert die Sonnenkaskaden einmal für beide Augen. Schattenqualität und -distanz steuert weiterhin das Spiel.",
  ["Scope lens stabilization"] = "Stabilisierung der Zielfernrohrlinse",
  ["Magnifying scope lenses while the view moves: share of the stabilised image (percent). Higher: no blinking of lights and grates, softer. 0 = off. Standing still the lens is untouched."] = "Vergrößernde Zielfernrohrlinsen bei bewegter Sicht: Anteil des stabilisierten Bilds (Prozent). Höher: kein Flackern von Lichtern und Gittern, weicher. 0 = aus. Im Stillstand bleibt die Linse unverändert.",
  ["VARIABLE RATE SHADING"] = "VARIABLE RATE SHADING",
  ["Peripheral shading"] = "Rand-Shading",
  [" 2 x 2"] = " 2 x 2",
  [" 4 x 4"] = " 4 x 4",
  ["Opaque scene materials in both eyes. The center stays 1 x 1. Unsupported 4 x 4 falls back to 2 x 2."] = "Undurchsichtige Szenenmaterialien in beiden Augen. Die Mitte bleibt 1 x 1. Nicht unterstütztes 4 x 4 fällt auf 2 x 2 zurück.",
  ["Unavailable: GPU resource error"] = "Nicht verfügbar: GPU-Ressourcenfehler",
  ["VRS Tier 2 unavailable"] = "VRS Tier 2 nicht verfügbar",
  ["Preparing"] = "Vorbereitung",
  ["%s | %u px tiles"] = "%s | %u-px-Kacheln",
  ["4 x 4"] = "4 x 4",
  ["2 x 2"] = "2 x 2",
  ["HIDDEN AREA MASK"] = "MASKE FÜR VERDECKTE BEREICHE",
  ["Mask lens edges"] = "Linsenränder maskieren",
  ["Skips shading the parts of each eye image the lens never shows. The visible area is unchanged."] = "Lässt die Teile jedes Augenbilds aus, die die Linse nie zeigt. Der sichtbare Bereich bleibt gleich.",
  ["Visible radius"] = "Sichtbarer Radius",
  ["Size of the shaded area as a percentage of the eye's field of view: 100%% touches its edges, 141%% masks nothing inside it.\nLower it until a dark border appears at the edge of the lens, then raise it until the border is gone."] = "Größe des schattierten Bereichs in Prozent des Augen-Sichtfelds: 100%% berührt seine Ränder, 141%% maskiert innen nichts.\nVerringern, bis am Linsenrand ein dunkler Rand erscheint, dann erhöhen, bis er verschwindet.",
  ["Waiting for the scene depth"] = "Warte auf die Szenentiefe",
  ["Masked %.1f %% / %.1f %% of pixels (MAIN / VRCAM)"] = "Maskiert %.1f %% / %.1f %% der Pixel (MAIN / VRCAM)",
  ["GAME MENUS"] = "SPIELMENÜS",
  ["VR menu quad"] = "VR-Menü-Fläche",
  ["VR menu FOV"] = "VR-Menü-FOV",
  ["Tracking / Camera"] = "Tracking / Kamera",
  ["Locomotion direction is set in the Controls tab."] = "Die Bewegungsrichtung wird im Tab Steuerung eingestellt.",
  ["Disable Mouse Y (Pitch)"] = "Maus Y deaktivieren (Nicken)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Unterdrückt das Nicken von Maus/rechtem Stick, damit nur das HMD den\nvertikalen Blick steuert. Angewendet von der CET-VRIK-Mod und der\nXInput-Zusammenführung. Standardmäßig an.",
  ["Head X right"] = "Kopf X rechts",
  ["Head Y forward"] = "Kopf Y vorn",
  ["Head Z up"] = "Kopf Z hoch",
  ["Debug Gizmos"] = "Debug-Gizmos",
  ["Raw hand overlay / debug gizmos:"] = "Rohes Hand-Overlay / Debug-Gizmos:",
  ["Enable hand overlay"] = "Hand-Overlay aktivieren",
  ["Draw 3D hand proxy"] = "3D-Handproxy zeichnen",
  ["Draw debug wire/axes"] = "Debug-Drahtgitter/Achsen zeichnen",
  ["Locator scale"] = "Locator-Skalierung",
  ["Verbose log (spammy diag)"] = "Ausführliches Protokoll (viel Diagnose)",
  ["Off by default for a clean cyberpunkvrport.log. Enable only\nwhen capturing ClipCursor / depth / hook diagnostics."] = "Standardmäßig aus für ein sauberes cyberpunkvrport.log. Nur aktivieren,\nwenn ClipCursor- / Tiefen- / Hook-Diagnosen erfasst werden.",
  ["FRAMEGEN"] = "FRAME-GEN",
  ["Enable frame generation"] = "Frame-Generierung aktivieren",
  ["While frame generation is enabled, hand smoothing runs at its rate times xr_hand_lerp_framegen_scale (1.5; 0 turns it off)."] = "Bei aktiver Frame-Generierung läuft die Handglättung mit ihrer Rate mal xr_hand_lerp_framegen_scale (1.5; 0 schaltet sie aus).",
  ["Frame generator"] = "Frame-Generator",
  ["FidelityFX"] = "FidelityFX",
  ["NVIDIA OFA + FidelityFX"] = "NVIDIA OFA + FidelityFX",
  ["NVIDIA DLSS Frame Generation"] = "NVIDIA DLSS Frame Generation",
  ["DLSS Frame Generation is not available here (%s); FidelityFX is used."] = "DLSS Frame Generation ist hier nicht verfügbar (%s); FidelityFX wird verwendet.",
  ["NVIDIA optical flow is not available on this GPU; FidelityFX optical flow is used."] = "NVIDIA Optical Flow ist auf dieser GPU nicht verfügbar; FidelityFX Optical Flow wird verwendet.",
  ["NVIDIA quality"] = "NVIDIA-Qualität",
  ["Fast (performance)"] = "Schnell (Leistung)",
  ["Medium (balanced)"] = "Mittel (ausgewogen)",
  ["Slow (best)"] = "Langsam (beste)",
  ["Optical flow"] = "Optical Flow",
  ["Off (game vectors only)"] = "Aus (nur Spielvektoren)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Die Bewegungsvektoren des Spiels beschreiben fast alle Bewegung; Optical Flow kostet GPU-Zeit\nund Speicher für das, was ihnen entgeht (einige Partikel und Effekte).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "NVIDIAs Frame-Generierungsmodell auf den Bewegungsvektoren und der Tiefe des Spiels. Höchste Qualität, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Adaptive Taktung echter Bilder",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Bis zur halben Headset-Bildrate. Lässt generierten Bildern mehr GPU-Zeit, wenn benachbarte echte Bilder verpasst werden.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Nutzt Bewegungsvektoren und Tiefe des Spiels in beiden Augen. Fügt ein Zwischenbild zwischen echten Bildern ein.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "HUD-Panel aktivieren",
  ["Head / free-look cone"] = "Kopf / Freisicht-Kegel",
  ["Follow"] = "Folgen",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Holt außerhalb des Kegels auf oder nach 3 Sekunden Ruhe, wenn der Gierversatz darin über 10° liegt.",
  ["HUD FOV"] = "HUD-FOV",
  ["Stereo depth"] = "Stereotiefe",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Aus: Das HUD hat in beiden Augen dieselbe Richtung.\nAn: platziert es in der gewählten physischen Tiefe.",
  ["Depth"] = "Tiefe",
  ["Brightness"] = "Helligkeit",
  ["Shadow / outline"] = "Schatten / Kontur",
  ["Glow"] = "Leuchten",
  ["INTERACTIONS / DIALOGS"] = "INTERAKTIONEN / DIALOGE",
  ["World-space interactions / dialogs"] = "Interaktionen / Dialoge im Raum",
  ["Interaction free-look cone"] = "Freisicht-Kegel für Interaktionen",
  ["Loot free-look cone"] = "Freisicht-Kegel für Beute",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Wird genutzt, solange Beutepanel und Gegenstandsbeschreibung sichtbar sind. Standard: 10°.",
  ["Interaction distance"] = "Interaktionsabstand",
  ["Interaction FOV"] = "Interaktions-FOV",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Interaktionshinweise und Dialogoptionen teilen sich dieses Panel. Es folgt nur außerhalb des Kegels; kein verzögertes Aufholen in Ruhe.",
  ["Element"] = "Element",
  ["Not currently visible in gameplay; settings are still saved."] = "Im Spiel derzeit nicht sichtbar; Einstellungen werden trotzdem gespeichert.",
  ["Show element"] = "Element anzeigen",
  ["Horizontal offset"] = "Horizontaler Versatz",
  ["Vertical offset"] = "Vertikaler Versatz",
  ["Size"] = "Größe",
  ["Opacity"] = "Deckkraft",
  ["Reset element"] = "Element zurücksetzen",
  ["Reset all elements"] = "Alle Elemente zurücksetzen",
  ["CONTROLS"] = "STEUERUNG",
  ["DRIVING"] = "FAHREN",
  ["BINDINGS"] = "BELEGUNG",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Bewegung, Waffenzielen und Abkürzungen für physische Interaktion.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Handzielen  (aus = entkoppeltes VR-Kopfzielen)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "AN (Handzielen): Der Controller richtet die Waffe aus und VRIK steuert die Arme.\nAUS (entkoppeltes VR-Kopfzielen): Die WAFFE folgt stattdessen deinem Kopf, das Spiel\nbehält ihre Position und ADS-Animationen, und VRIK gibt den\nWaffenarm frei. So oder so verlässt der Schuss die echte Mündung, für Kugeln und\nProjektile gleichermaßen, und die Freisicht beim Zielen bleibt erhalten.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Laserpunkt der Waffe (wo die Kugel trifft)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Roter Punkt, projiziert aus der tatsächlichen Mündungsrichtung durch die\nSpielkamera -- zeigt genau, wohin die Kugel fliegt.",
  ["Controller vibration"] = "Controller-Vibration",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Haptik: jeder Schuss nach Waffenklasse (Handfeuerwaffe, Gewehr, Schrotflinte, Scharfschütze),\nNahkampfblock und Parade, Kugelblock und Ablenkung, Erreichen eines Gürtelelements,\nZiehen eines Granatsplints. Beidhändiger Griff: beide Hände; einhändig: eine.",
  ["Vibration strength"] = "Vibrationsstärke",
  ["Enable VR -> XInput merge"] = "VR -> XInput-Zusammenführung aktivieren",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Verknüpft (OR) den VR-Controllerzustand bei jeder Abfrage mit XInput-Gamepad 0.\nAus = das Spiel sieht nur ein physisches Pad / nichts.",
  ["Weapon holsters (reach + right grip)"] = "Waffenholster (Greifen + rechter Griff)",
  ["Immersive holsters"] = "Immersive Holster",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "AN  - die Waffe wird durch das SICHTBARE Holster bestimmt, nach dem du greifst:\n      über der rechten Schulter = Primärwaffe (Gewehr / Scharfschütze),\n      Hüfte mit Katana = Nahkampf, Hüfte mit Pistole = Seitenwaffe.\nAUS - sichtbare Holster ignorieren, fester Slot pro Zone:\n      über der Schulter = EquipmentSlot1, rechte Hüfte = Slot2, linke Hüfte = Slot3.\nZur Zone greifen und den RECHTEN Griff drücken, um auszurüsten / abzulegen.",
  ["Locomotion direction"] = "Bewegungsrichtung",
  ["Analog movement"] = "Analoge Bewegung",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "An: Geschwindigkeit folgt dem Weg des linken Sticks. Aus: die bisherige Bewegung mit fester Geschwindigkeit (Standard).\nFahrzeugsteuerung behält ihr bisheriges Verhalten.",
  ["Left stick deadzone"] = "Totzone linker Stick",
  ["Right stick deadzone"] = "Totzone rechter Stick",
  ["Full input threshold"] = "Schwelle für vollen Ausschlag",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Roher Weg, der vollen analogen Ausschlag ergibt und Sprint, Ausweichen und Ducken auslöst.\nDer nutzbare Weg zwischen Totzone und dieser Schwelle entspricht 0-100%%.",
  ["Game (camera)"] = "Spiel (Kamera)",
  ["HMD (head)"] = "HMD (Kopf)",
  ["Left hand"] = "Linke Hand",
  ["Right hand"] = "Rechte Hand",
  ["Move source"] = "Bewegungsquelle",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Spiel    - der linke Stick läuft in Kamerarichtung (Original).\nHMD      - der linke Stick läuft in Blickrichtung des Headsets.\nLinke/rechte Hand - läuft dorthin, wohin der gewählte Controller zeigt.\nFahrzeuge behalten immer die Spielrichtung.",
  ["Breaststroke swimming"] = "Brustschwimmen",
  ["Physical crouch"] = "Physisches Ducken",
  ["Physical crouch depth"] = "Tiefe des physischen Duckens",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Höhenverlust nach der gemessenen Neigung. Aufrichten beendet das physische Ducken.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "Im Wasser: mit beiden Händen nach vorn greifen, nach außen ziehen und zurückziehen.\nDie Bewegung beginnt beim Zug. Sanfte Züge schwimmen normal; schnelle Züge geben Schub.\nGeschwommen wird, wohin das Headset zeigt, auch hoch/runter; kein Stick nötig.\nZum Aufsteigen getrennte Hände auf Brusthöhe heben und beide nach unten drücken.\nZüge wiederholen, um weiterzuschwimmen. Linken Stick zurückziehen zum Anhalten.",
  ["Ladder grip climbing"] = "Leiterklettern mit Griffen",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Eine Seitenholme oder Sprosse greifen. Hand nach unten ziehen, um hochzuklettern,\noder nach oben bewegen, um hinabzuklettern. Loslassen zum Anhalten. Becken und Beine bleiben an der Leiter.",
  ["Auto finish near ladder top"] = "Automatisch oben an der Leiter abschließen",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Nach einem Zug nach oben nahe dem Ende wird das Klettern abgeschlossen, auch wenn die Griffe gelöst sind.\nStick bewegen oder eine haltende Hand nach oben drücken, um abzubrechen.",
  ["Ladder finish distance"] = "Abschlussabstand Leiter",
  ["Turning (right stick)"] = "Drehen (rechter Stick)",
  ["Snap turn"] = "Snap-Drehung",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Wandelt die X-Achse des rechten Sticks in einzelne Drehschritte\nstatt einer fließenden Drehung um. Hilft gegen Reisekrankheit.",
  ["Snap angle"] = "Snap-Winkel",
  ["STEREO"] = "STEREO",
  ["PERFORMANCE"] = "LEISTUNG",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Spieleinstellung",
  ["Off (higher FPS)"] = "Aus (höhere FPS)",
  ["On (lower latency)"] = "An (geringere Latenz)",
  ["On + Boost"] = "An + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Aus kann GPU-Auslastung und FPS verbessern, aber die Eingabelatenz erhöhen.",
  ["On"] = "An",
  ["Waiting for renderer"] = "Warte auf Renderer",
  ["Applied: %s"] = "Angewendet: %s",
  ["STEREO VIEW"] = "STEREOANSICHT",
  ["Mono mode"] = "Mono-Modus",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Ein Bild für beide Augen, einmal aus der Kopfmitte gerendert:\nkeine Tiefe, die meisten Bilder pro Sekunde. Engine-Stereo und die zweite Ansicht sind aus.",
  ["Restart the game to apply"] = "Spiel neu starten, um es anzuwenden",
  ["Motion prediction (ms)"] = "Bewegungsvorhersage (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Sagt die Kopfpose um so viele ms anhand der Kopf-\ngeschwindigkeit voraus und verbirgt die Render-zu-Photon-Latenz. 0 = aus.\nErhöhen, bis sich Bewegung direkt anfühlt, ohne zu überschießen.",
  ["Stereo separation x"] = "Stereotrennung x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Persönliche Feinabstimmung der Auto-IPD. 1.0 = kalibrierte natürliche\nTrennung, automatisch an die Laufzeit-IPD des Headsets skaliert. Für den Geschmack\n0.8-1.2; 3-5x übertreibt die Tiefe und macht den\nAugenwechsel auf dem flachen Monitor zum Testen sichtbar.",
  ["World scale"] = "Weltmaßstab",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Skaliert Augenabstand UND Kopfbewegung zusammen.\nSenken (z. B. 0.8), damit die Welt\nGRÖSSER / du kleiner wirkst; erhöhen, um die Welt zu verkleinern. Nutzen, wenn V\nund NPCs zu groß wirken.",
  ["IPD scale"] = "IPD-Skalierung",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Multiplikator des Augenabstands auf die Laufzeit-IPD. 1.0 = neutrale\nBasis (+-0.033 m bei einem typischen Headset).\nBeeinflusst die Stereotiefe (Diorama vs. Riese), NICHT die monokulare Größe.",
  ["Reuse last clean frame"] = "Letztes sauberes Bild wiederverwenden",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Bei veralteten Ticks das letzte saubere erfasste Auge erneut übergeben und\nvom Compositor reprojizieren lassen, statt veralteten Inhalt\nerneut zu warpen. Kann die Übergaberate\nRichtung Erfassungsrate senken. Aus = das veraltete Auge immer warpen.",
  ["Asymmetric projection"] = "Asymmetrische Projektion",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "AN: Jedes Auge rendert genau sein eigenes außermittiges Linsenfenster\n(mehr vom Panel genutzt, quadratische Pixel).\nAUS: der symmetrische Frustum nach dem breitesten Halbwinkel.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "VR-Kurzbefehle und Standardaktionen des Spiels. Tastennamen folgen der Touch-/Xbox-Konvention; Spielaktionen nutzen deine Controller-Belegung.",
  ["LEFT STICK"] = "LINKER STICK",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Bewegen. 0.2 Sekunden voll nach vorn halten zum Sprinten.",
  ["RIGHT STICK  Left / right"] = "RECHTER STICK  Links / rechts",
  ["Turn. Uses your snap-turn setting."] = "Drehen. Nutzt deine Snap-Dreh-Einstellung.",
  ["RIGHT STICK  Full up"] = "RECHTER STICK  Voll hoch",
  ["Dash / dodge once per push."] = "Sprint-Ausweichen / Ausweichen, einmal pro Stoß.",
